mapper.select:
SELECT stat_date     AS statDate,
       SUM(qty_sold) AS qtySold
FROM order_sales_daily
WHERE sku_id = #{skuId}
  AND stat_date >= #{dateFrom}
  AND stat_date <= #{dateTo}
GROUP BY stat_date
ORDER BY stat_date

SELECT stat_date        AS statDate,
       SUM(qty_on_hand) AS qtyOnHand
FROM inventory_snapshot_daily
WHERE sku_id = #{skuId}
  AND stat_date >= #{dateFrom}
  AND stat_date <= #{dateTo}
GROUP BY stat_date
ORDER BY stat_date
